"""Ledger's append-only log: every change, one line each, oldest first.
Each line is `crc json`, so a record torn by a crash can be told from a good one."""
import json
import os
import zlib


def encode(record):
    body = json.dumps(record)
    return f"{zlib.crc32(body.encode()):08x} {body}\n"


def decode(line):
    """The record on one line (bytes), or None if the line is torn or damaged."""
    if not line.endswith(b"\n"):
        return None
    crc, _, body = line.decode("utf-8", "replace").rstrip("\n").partition(" ")
    if crc != f"{zlib.crc32(body.encode()):08x}":
        return None
    try:
        return json.loads(body)
    except ValueError:
        return None


class Log:
    def __init__(self, path):
        self.path = path
        if os.path.exists(path + ".tmp"):
            # a compaction crashed before its swap: the old log is still whole, so drop the copy
            os.remove(path + ".tmp")

    def append(self, record):
        with open(self.path, "a", encoding="utf-8") as fh:
            fh.write(encode(record))
            fh.flush()
            os.fsync(fh.fileno())

    def read(self):
        if not os.path.exists(self.path):
            return []
        records, good = [], 0
        with open(self.path, "rb") as fh:
            for line in fh:
                record = decode(line)
                if record is None:
                    break
                records.append(record)
                good += len(line)
        if good < os.path.getsize(self.path):
            with open(self.path, "r+b") as fh:
                fh.truncate(good)
        return records

    def rewrite(self, records):
        """Replace the whole log with these records, all at once: a crash leaves
        the old log or the new one, never half of each."""
        tmp = self.path + ".tmp"
        with open(tmp, "w", encoding="utf-8") as fh:
            for record in records:
                fh.write(encode(record))
            fh.flush()
            os.fsync(fh.fileno())
        os.replace(tmp, self.path)

